    {
      "name": "Polynomial.map_taylor",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "theorem",
      "type": "∀ {R : Type u_2} {S : Type u_3} [inst : Semiring R] [inst_1 : Semiring S] (p : Polynomial R) (r : R) (f : R →+* S),\n  Polynomial.map f ((Polynomial.taylor r) p) = (Polynomial.taylor (f r)) (Polynomial.map f p)"
    },
    {
      "name": "MvPolynomial.map_eval₂",
      "module_name": "Mathlib.Algebra.MvPolynomial.Eval",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S₁ : Type v} {S₂ : Type w} {S₃ : Type x} [inst : CommSemiring R] [inst_1 : CommSemiring S₁]\n  (f : R →+* S₁) (g : S₂ → MvPolynomial S₃ R) (p : MvPolynomial S₂ R),\n  (MvPolynomial.map f) (MvPolynomial.eval₂ MvPolynomial.C g p) =\n    MvPolynomial.eval₂ MvPolynomial.C (⇑(MvPolynomial.map f) ∘ g) ((MvPolynomial.map f) p)"
    },
    {
      "name": "MvPowerSeries.coeff_map",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Basic",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} {S : Type u_3} [inst : Semiring R] [inst_1 : Semiring S] (f : R →+* S) (n : σ →₀ ℕ)\n  (φ : MvPowerSeries σ R), (MvPowerSeries.coeff n) ((MvPowerSeries.map f) φ) = f ((MvPowerSeries.coeff n) φ)"
    },
    {
      "name": "Polynomial.taylorAlgHom",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : CommSemiring R] → R → Polynomial R →ₐ[R] Polynomial R"
    },
    {
      "name": "MvPowerSeries.mapAlgHom",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Basic",
      "kind": "definition",
      "type": "{σ : Type u_1} →\n  {R : Type u_2} →\n    {A : Type u_3} →\n      [inst : CommSemiring R] →\n        [inst_1 : Semiring A] →\n          [inst_2 : Algebra R A] →\n            {B : Type u_4} →\n              [inst_3 : Semiring B] → [inst_4 : Algebra R B] → (A →ₐ[R] B) → MvPowerSeries σ A →ₐ[R] MvPowerSeries σ B"
    },
    {
      "name": "Polynomial.taylorAlgHom_apply",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommSemiring R] (r : R) (a : Polynomial R),\n  (Polynomial.taylorAlgHom r) a = (Polynomial.taylor r) a"
    }
  ]
}

