    {
      "name": "Polynomial.algEquivAevalXAddC_apply",
      "module_name": "Mathlib.Algebra.Polynomial.AlgebraMap",
      "kind": "theorem",
      "type": "∀ {R : Type u_3} [inst : CommRing R] (t : R) (a : Polynomial R),\n  (Polynomial.algEquivAevalXAddC t) a = (Polynomial.aeval (Polynomial.X + Polynomial.C t)) a"
    },
    {
      "name": "MvPowerSeries.map_subst",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommRing R] {τ : Type u_4} {S : Type u_5} [inst_1 : CommRing S] [Finite σ]\n  {a : σ → MvPowerSeries τ R},\n  MvPowerSeries.HasSubst a →\n    ∀ {h : R →+* S} (f : MvPowerSeries σ R),\n      (MvPowerSeries.map h) (MvPowerSeries.subst a f) =\n        MvPowerSeries.subst (fun i => (MvPowerSeries.map h) (a i)) ((MvPowerSeries.map h) f)"
    },
    {
      "name": "PowerSeries.map_subst",
      "module_name": "Mathlib.RingTheory.PowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {R : Type u_2} [inst : CommRing R] {τ : Type u_3} {S : Type u_4} [inst_1 : CommRing S] {a : MvPowerSeries τ R},\n  PowerSeries.HasSubst a →\n    ∀ {h : R →+* S} (f : PowerSeries R),\n      (MvPowerSeries.map h) (PowerSeries.subst a f) =\n        PowerSeries.subst ((MvPowerSeries.map h) a) ((PowerSeries.map h) f)"
    },
    {
      "name": "MvPolynomial.hom_bind₁",
      "module_name": "Mathlib.Algebra.MvPolynomial.Monad",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_3} {S : Type u_4} [inst : CommSemiring R] [inst_1 : CommSemiring S]\n  (f : MvPolynomial τ R →+* S) (g : σ → MvPolynomial τ R) (φ : MvPolynomial σ R),\n  f ((MvPolynomial.bind₁ g) φ) = (MvPolynomial.eval₂Hom (f.comp MvPolynomial.C) fun i => f (g i)) φ"
    },
    {
      "name": "PowerSeries.coeff_subst'",
      "module_name": "Mathlib.RingTheory.PowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {R : Type u_2} [inst : CommRing R] {S : Type u_4} [inst_1 : CommRing S] [inst_2 : Algebra R S] {b : PowerSeries S},\n  PowerSeries.HasSubst b →\n    ∀ (f : PowerSeries R) (e : ℕ),\n      (PowerSeries.coeff e) (PowerSeries.subst b f) =\n        ∑ᶠ (d : ℕ), (PowerSeries.coeff d) f • (PowerSeries.coeff e) (b ^ d)"
    }
  ]
}

